import numpy as np
from scipy.ndimage import label
A=np.load('source_pixels.npz')['rgb']
for t in range(96):
 p=A[t].astype(float);mx=p.max(2);mn=p.min(2);m=(mn>165)&((mx-mn)<28)
 lab,n=label(m); out=[]
 for i in range(1,n+1):
  yy,xx=np.where(lab==i)
  if len(xx)>=3 and 75<xx.mean()<180 and 35<yy.mean()<110 and np.ptp(xx)<12 and np.ptp(yy)<12:
   out.append((len(xx),round(xx.mean(),1),round(yy.mean(),1),round(mn[yy,xx].mean())))
 if t<20 or t%5==0: print(t,sorted(out,reverse=True)[:10])
PY"
